11	// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard): an account whose homeworld
12	// holds a wall must spend a login on the sibling that holds nothing, not on growing the wall it already
13	// has. The colony is planted first so the sibling is bare from the moment the wall stands.
14	test('a walled homeworld reaches its naked colony with a wall order', function (): void {
15	    $situation = Situation::of($this)
16	        ->levelEveryPlanet('robot_factory', 2)
17	        ->levelEveryPlanet('shipyard', 4)
18	        ->levelEveryPlanet('solar_plant', 30)
19	        ->colony()
20	        ->defence('light_laser', 1_200)
21	        ->stockEveryPlanet(5_000_000, 5_000_000, 5_000_000)
22	        ->session();
23	
24	    $situation->expectQueued('rocket_launcher')
25	        ->expectWork(AiWorkKind::QueueUnits);
26	});
27	
28	// The same invariant at the other end of the account's life: a colony planted after the wall exists has no
29	// shipyard, so the wall cannot be ordered on it until the yard stands. The account must reach it anyway,
30	// by putting the yard it waits on into the build queue.
31	test('a walled homeworld reaches its naked colony that has no yard yet', function (): void {
32	    $situation = Situation::of($this)
33	        ->level('robot_factory', 2)
34	        ->level('shipyard', 4)
35	        ->level('solar_plant', 30)
36	        ->colony()
37	        ->defence('light_laser', 1_200)
38	        ->stockEveryPlanet(5_000_000, 5_000_000, 5_000_000)
39	        ->session();
40	
41	    $situation->expectQueued('shipyard');
42	});

