 61	            $time_countdown = $item->time_end - (int)Date::now()->timestamp;
 62	            if ($time_countdown < 0) {
 63	                $time_countdown = 0;
 64	            }
 65	
 66	            // Calculate when next unit will be processed and given.
 67	            $time_per_unit = ($item->time_end - $item->time_start) / $item->object_amount;
