 75	            $time_countdown_next_single = $time_per_unit - $last_update_diff;
 76	
 77	            $viewModel = new UnitQueueViewModel(
 78	                $item['id'],
 79	                $object,
 80	                $time_countdown,
 81	                $item['time_end'] - $item['time_start'],
 82	                $item['object_amount'],
